.header{height:52px;background:var(--bg2);border-bottom:1px solid var(--border);display:flex;align-items:center;justify-content:space-between;padding:0 20px;flex-shrink:0;}
.logo{font-weight:700;font-size:15px;}.logo span{color:var(--p);}
.model-badge{font-family:var(--mono);font-size:10px;color:var(--pL);background:rgba(124,113,240,.1);border:1px solid var(--border2);padding:3px 10px;border-radius:12px;display:flex;align-items:center;gap:6px;}
.model-dot{width:5px;height:5px;border-radius:50%;background:var(--teal);animation:pulse 2s infinite;}
@keyframes pulse{0%,100%{opacity:1}50%{opacity:.3}}

.messages{flex:1;overflow-y:auto;padding:24px 20px;display:flex;flex-direction:column;gap:16px;max-width:800px;margin:0 auto;width:100%;}
.messages::-webkit-scrollbar{width:4px;}.messages::-webkit-scrollbar-thumb{background:var(--text3);border-radius:2px;}

.msg{display:flex;gap:12px;align-items:flex-start;}
.msg.user{flex-direction:row-reverse;}
.msg-avatar{width:32px;height:32px;border-radius:8px;flex-shrink:0;display:flex;align-items:center;justify-content:center;font-size:13px;}
.msg.ai .msg-avatar{background:linear-gradient(135deg,var(--p),var(--teal));}
.msg.user .msg-avatar{background:var(--bg3);border:1px solid var(--border);color:var(--text2);}
.msg-content{max-width:75%;}
.msg-bubble{padding:12px 16px;border-radius:12px;font-size:14px;line-height:1.65;}
.msg.ai .msg-bubble{background:var(--bg2);border:1px solid var(--border);color:var(--text2);}
.msg.ai .msg-bubble strong{color:var(--text);}
.msg.user .msg-bubble{background:rgba(124,113,240,.15);border:1px solid var(--border2);color:var(--text);}
.msg-meta{font-size:10px;color:var(--text3);font-family:var(--mono);margin-top:4px;padding:0 4px;}
.msg.user .msg-meta{text-align:right;}

.typing{display:flex;gap:4px;align-items:center;padding:8px 4px;}
.typing-dot{width:6px;height:6px;border-radius:50%;background:var(--text3);animation:typing .9s infinite;}
.typing-dot:nth-child(2){animation-delay:.2s;}
.typing-dot:nth-child(3){animation-delay:.4s;}
@keyframes typing{0%,60%,100%{transform:translateY(0)}30%{transform:translateY(-6px)}}

.welcome{text-align:center;padding:60px 20px;color:var(--text2);}
.welcome h2{font-size:28px;color:var(--text);margin-bottom:8px;font-weight:400;}
.welcome h2 em{font-style:italic;color:var(--pL);}
.welcome p{font-size:14px;margin-bottom:28px;line-height:1.7;}
.quick-prompts{display:flex;flex-wrap:wrap;gap:8px;justify-content:center;}
.quick-btn{background:var(--bg2);border:1px solid var(--border);padding:8px 16px;border-radius:20px;font-size:12px;color:var(--text2);cursor:pointer;transition:all .15s;}
.quick-btn:hover{border-color:var(--p);color:var(--pL);}

.input-area{border-top:1px solid var(--border);padding:16px 20px;background:var(--bg2);flex-shrink:0;}
.input-wrap{max-width:800px;margin:0 auto;display:flex;gap:10px;align-items:flex-end;}
.input-box{flex:1;background:var(--bg3);border:1px solid var(--border);border-radius:12px;padding:12px 16px;color:var(--text);font-size:14px;font-family:inherit;resize:none;outline:none;min-height:46px;max-height:120px;line-height:1.5;}
.input-box:focus{border-color:var(--p);}
.input-box::placeholder{color:var(--text3);}
.send-btn{width:44px;height:44px;border-radius:10px;background:var(--p);border:none;color:#fff;cursor:pointer;font-size:16px;flex-shrink:0;transition:opacity .15s;}
.send-btn:hover{opacity:.85;}
.send-btn:disabled{opacity:.4;cursor:not-allowed;}

/* Model info bar */
.info-bar{text-align:center;padding:6px;font-family:var(--mono);font-size:10px;color:var(--text3);background:var(--bg);}
</style>
</head>
